## Project structure:
- Server project: `/tmp/sv-1635b4be967d476d91936c6c73a6b5ae/ShipmentTracker/ShipmentTracker/`
- Client project: `/tmp/sv-1635b4be967d476d91936c6c73a6b5ae/ShipmentTracker/ShipmentTracker.Client/`

## What to implement:

### 1. Remove template defaults
Delete these files from the Client project's Pages folder:
- `Counter.razor`
- `Weather.razor`

### 2. Create shared models in Client project

Create `/tmp/sv-1635b4be967d476d91936c6c73a6b5ae/ShipmentTracker/ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

### 3. Create service interface in Client project

Create `/tmp/sv-1635b4be967d476d91936c6c73a6b5ae/ShipmentTracker/ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<List<Shipment>> GetShipmentsByStatusAsync(ShipmentStatus? status);
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<List<Shipment>> GetShipmentsForCustomerAsync(string email);
    Task<Shipment> CreateShipmentAsync(Shipment shipment);
    Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 4. Create Client-side implementation using HttpClient

Create `/tmp/sv-1635b4be967d476d91936c6c73a6b5ae/ShipmentTracker/ShipmentTracker.Client/Services/ShipmentServiceClient.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentServiceClient(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<List<Shipment>> GetShipmentsByStatusAsync(ShipmentStatus? status)
    {
        var url = status.HasValue ? $"api/shipments?status={status}" : "api/shipments";
        return await http.GetFromJsonAsync<List<Shipment>>(url) ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");
    }

    public async Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        return await http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(email)}") ?? [];
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var response = await http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{id}/status", status);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }
}
```

### 5. Register HttpClient and service in Client Program.cs

Edit `/tmp/sv-1635b4be967d476d91936c6c73a6b5ae/ShipmentTracker/ShipmentTracker.Client/Program.cs` to:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddHttpClient("ShipmentTracker.ServerAPI", client =>
    client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress));
builder.Services.AddScoped(sp =>
    sp.GetRequiredService<IHttpClientFactory>().CreateClient("ShipmentTracker.ServerAPI"));
builder.Services.AddScoped<IShipmentService, ShipmentServiceClient>();

await builder.Build().RunAsync();
```

### 6. Create server-side service implementation

Create `/tmp/sv-1635b4be967d476d91936c6c73a6b5ae/ShipmentTracker/ShipmentTracker/Services/ShipmentServiceServer.cs`:
```csharp
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ShipmentServiceServer : IShipmentService
{
    // In-memory store for demo; replace with EF Core in production
    private static readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, USA", Destination = "London, UK", Status = ShipmentStatus.InTransit, CreatedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new Shipment { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = ShipmentStatus.PickedUp, CreatedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(7), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new Shipment { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, Germany", Destination = "Tokyo, Japan", Status = ShipmentStatus.Delivered, CreatedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "alice@example.com", Description = "Auto parts - 5 boxes" },
        new Shipment { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "Sydney, Australia", Destination = "Dubai, UAE", Status = ShipmentStatus.Delayed, CreatedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "charlie@example.com", Description = "Perishable goods - refrigerated" },
        new Shipment { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "São Paulo, Brazil", Destination = "Miami, USA", Status = ShipmentStatus.OutForDelivery, CreatedDate = DateTime.UtcNow.AddDays(-4), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "bob@example.com", Description = "Textiles - 3 cartons" },
    };
    private static int _nextId = 6;

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<List<Shipment>> GetShipmentsByStatusAsync(ShipmentStatus? status)
    {
        if (!status.HasValue)
            return Task.FromResult(_shipments.ToList());
        return Task.FromResult(_shipments.Where(s => s.Status == status.Value).ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return Task.FromResult(_shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase)));
    }

    public Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        return Task.FromResult(_shipments.Where(s =>
            s.CustomerEmail.Equals(email, StringComparison.OrdinalIgnoreCase)).ToList());
    }

    public Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.Id = _nextId++;
        shipment.CreatedDate = DateTime.UtcNow;
        _shipments.Add(shipment);
        return Task.FromResult(shipment);
    }

    public Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id)
            ?? throw new InvalidOperationException($"Shipment {id} not found");
        shipment.Status = status;
        return Task.FromResult(shipment);
    }
}
```

### 7. Create API endpoints

Create `/tmp/sv-1635b4be967d476d91936c6c73a6b5ae/ShipmentTracker/ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:
```csharp
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (ShipmentStatus? status, IShipmentService service) =>
            await service.GetShipmentsByStatusAsync(status));

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("/customer/{email}", async (string email, IShipmentService service) =>
            await service.GetShipmentsForCustomerAsync(email));

        group.MapPost("/", async (Shipment shipment, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(shipment);
            return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
        });

        group.MapPut("/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
        {
            var updated = await service.UpdateShipmentStatusAsync(id, status);
            return Results.Ok(updated);
        });
    }
}
