namespace ShipmentTracker.Services;

public class ShipmentServiceServer : IShipmentService
{
    // In-memory store for demo; replace with EF Core in production
    private static readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, USA", Destination = "London, UK", Status = ShipmentStatus.InTransit, CreatedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new Shipment { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = ShipmentStatus.PickedUp, CreatedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(7), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new Shipment { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, Germany", Destination = "Tokyo, Japan", Status = ShipmentStatus.Delivered, CreatedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "alice@example.com", Description = "Auto parts - 5 boxes" },
        new Shipment { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "Sydney, Australia", Destination = "Dubai, UAE", Status = ShipmentStatus.Delayed, CreatedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "charlie@example.com", Description = "Perishable goods - refrigerated" },
        new Shipment { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "São Paulo, Brazil", Destination = "Miami, USA", Status = ShipmentStatus.OutForDelivery, CreatedDate = DateTime.UtcNow.AddDays(-4), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "bob@example.com", Description = "Textiles - 3 cartons" },
    };
    private static int _nextId = 6;

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<List<Shipment>> GetShipmentsByStatusAsync(ShipmentStatus? status)
    {
        if (!status.HasValue)
            return Task.FromResult(_shipments.ToList());
        return Task.FromResult(_shipments.Where(s => s.Status == status.Value).ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return Task.FromResult(_shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase)));
    }

    public Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
    {
        return Task.FromResult(_shipments.Where(s =>
            s.CustomerEmail.Equals(email, StringComparison.OrdinalIgnoreCase)).ToList());
    }

    public Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.Id = _nextId++;
        shipment.CreatedDate = DateTime.UtcNow;
        _shipments.Add(shipment);
        return Task.FromResult(shipment);
    }

    public Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id)
            ?? throw new InvalidOperationException($"Shipment {id} not found");
        shipment.Status = status;
        return Task.FromResult(shipment);
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (ShipmentStatus? status, IShipmentService service) =>
            await service.GetShipmentsByStatusAsync(status));

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("/customer/{email}", async (string email, IShipmentService service) =>
            await service.GetShipmentsForCustomerAsync(email));

        group.MapPost("/", async (Shipment shipment, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(shipment);
            return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
        });

        group.MapPut("/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
        {
            var updated = await service.UpdateShipmentStatusAsync(id, status);
            return Results.Ok(updated);
        });
    }
}

