@code {
    private List<Shipment>? _shipments;
    private ShipmentStatus? _selectedStatus;
    private bool _showCreateForm;
    private Shipment _newShipment = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        _shipments = await ShipmentService.GetShipmentsByStatusAsync(_selectedStatus);
    }

    private async Task OnStatusFilterChanged(ChangeEventArgs e)
    {
        var value = e.Value?.ToString();
        _selectedStatus = string.IsNullOrEmpty(value) ? null : Enum.Parse<ShipmentStatus>(value);
        await LoadShipments();
    }

    private void ShowCreateForm()
    {
        _newShipment = new Shipment { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        _showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        _newShipment.TrackingNumber = $"TRK-{Random.Shared.Next(100, 999)}-{DateTime.UtcNow.Year}";
        _newShipment.Status = ShipmentStatus.Pending;
        await ShipmentService.CreateShipmentAsync(_newShipment);
        _showCreateForm = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            await LoadShipments();
        }
    }

